'use strict';

// MODULES //

var addon = require( './../src/addon.node' );


// MAIN //

/**
* Computes the sum of single-precision floating-point strided array elements, ignoring `NaN` values, using an improved Kahan–Babuška algorithm and alternative indexing semantics, and returning the number of non-`NaN` elements.
*
* @param {PositiveInteger} N - number of indexed elements
* @param {Float32Array} x - input array
* @param {integer} strideX - stride length for `x`
* @param {NonNegativeInteger} offsetX - starting index for `x`
* @param {Float32Array} sum - output array for storing the sum
* @param {NonNegativeInteger} offsetSum - starting index for `sum`
* @param {Int64Array} count - output array for storing the number of non-NaN elements
* @param {NonNegativeInteger} offsetCount - starting index for `count`
* @returns {Float32Array} `sum`
*
* @example
* var Float32Array = require( '@stdlib/array/float32' );
* var Int64Array = require( '@stdlib/array/int64' );
*
* var x = new Float32Array( [ 2.0, 1.0, 2.0, -2.0, -2.0, 2.0, 3.0, 4.0, NaN, NaN ] );
* var sum = new Float32Array( 1 );
* var count = new Int64Array( 1 );
*
* var v = snannsumkbn( 5, x, 2, 1, sum, 0, count, 0 );
* // returns <Float32Array>[ 5.0 ]
*
* var n = count.get( 0 );
* // returns <Int64>[ 4n ]
*/
function snannsumkbn( N, x, strideX, offsetX, sum, offsetSum, count, offsetCount ) { // eslint-disable-line max-len
	addon.ndarray( N, x, strideX, offsetX, sum, offsetSum, count._buffer, offsetCount ); // eslint-disable-line no-underscore-dangle, max-len
	return sum;
}


// EXPORTS //

module.exports = snannsumkbn;
